private void HandlePhases()
{
    // === Phase 2 ===
    // In phase 2, the shield is activated and the carrots appear
    // You need to destroy the carrots to make the shield disappear
    if (CurrentHealth == 50f && !Fase2 && !Fase3)
    {
        Fase2 = true;
        _shield.SetActive(true);

        foreach (GameObject carrot in _carrots)
        {
            carrot.SetActive(true);
        }
    }

    // === Transition to Phase 3 ===
    // Once all carrots are destroyed, move to phase 3
    if (!Fase3 && _grapplingScript.DestroyedCarrots == 6)
    {
        Destroy(_shield);
        CurrentHealth = 30f;
        Fase3 = true;
    }

    // === Phase 3 Logic ===
    // In phase 3, the boss throws minions as the last attack every few seconds
    if (Fase3 && !_minionsSpawned)
    {
        Debug.Log("Starting the last Phase and sending minions!");
        _minionsSpawned = true;
        StartCoroutine(SpawnMinions());
    }
}

