        {
            Destroy(this.gameObject, 0.5f);
        }
        //if the tray frisbee has reached the old marked position of the player move it back
        if ((Tray.transform.position == oldPlayerTransform && movingBack == false) || movingBack == true)
        {
            movingBack = true;
            Tray.transform.position = Vector3.MoveTowards(Tray.transform.position, projectilesTransform.transform.position, speed * Time.deltaTime);
        }
        //otherwise move the tray frisbee towards the old player transform
        else
        {
            Tray.transform.position = Vector3.MoveTowards(Tray.transform.position, oldPlayerTransform, speed * Time.deltaTime);
        }
    }
}

IEnumerator SpawnWaves()
{
    for (int wave = 1; wave <= totalWaves; wave++, waveCount++) // Go through each wave
    {
        // Spawn the enemies for this wave
        for (int i = 0; i < enemiesPerWave; i++)
        {
            SpawnEnemy(); // This spawns one enemy
            yield return new WaitForSeconds(timeBetweenEnemies); // Wait for 1 second before spawning the next one
        }
        //all enemies spawned

        yield return new WaitForSeconds(timeBetweenWaves); // Wait for 5 seconds before starting the next wave
        //all waves finished

    }

    //all waves complete
}

